insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9490, 28, 'Mehr nicht übertragbare Elterngeldmonate je Elternteil im bisherigen Umfang (Bund)', 'Reservierte Partnermonate erhöhen die Elternzeit von Vätern deutlich; Studien aus Deutschland und Québec zeigen danach dauerhaft mehr Haus- und Sorgearbeit der Väter, in Schweden fand sich kein solcher Effekt. Umbau im bestehenden Elterngeld ohne große Mehrkosten.', 'belegt', 'https://www.rwi-essen.de/publikationen/zitationsansicht/gemischt/detail/fathers-parental-leave-taking-childcare-involvement-and-1043', 'bund', null, true, 'blind'),
  (9491, 28, 'Elterngeld verlängern mit mehr nicht übertragbaren Monaten je Elternteil (Bund)', 'Reservierte Monate für jeden Elternteil verschieben laut Québec- und Deutschland-Studien die Hausarbeit dauerhaft zu den Vätern. Die Verlängerung des Bezugs verursacht aber erhebliche Mehrkosten und braucht Finanzierung.', 'belegt', 'https://ideas.repec.org/a/ucp/jlabec/doi10.1086-703115.html', 'bund', null, true, 'blind'),
  (9492, 28, 'Bezahlte Freistellung des zweiten Elternteils direkt nach der Geburt (Bund)', 'Kurze Partnerfreistellung wird stark genutzt und erleichtert Müttern den Wiedereinstieg; in Spanien änderte sie die längerfristige Aufteilung aber kaum. Gesetzlich einfach, umlage- oder steuerfinanziert machbar.', 'gemischt', 'https://www.iza.org/publications/dp/10865', 'bund', null, true, 'blind'),
  (9493, 28, 'Elterngeld bei Teilzeit und Partnerschaftsbonus verbessern (Bund)', 'ElterngeldPlus und Partnerschaftsbonus werden zunehmend genutzt, der Bonus aber nur von einem kleinen Teil der Väter; eine messbare Wirkung auf Aufteilung oder Rückkehr aus der Teilzeit ist kaum untersucht. Leicht im bestehenden Gesetz umsetzbar.', 'offen', 'https://www.bundestag.de/webarchiv/textarchiv/2018/kw08-de-elterngeld-plus-542316', 'bund', null, true, 'blind'),
  (9494, 28, 'Flexible Arbeitszeiten, Homeoffice und betriebliche Kinderbetreuung fördern (Bund)', 'Homeoffice erhöht laut Paneldaten die vertraglichen Stunden von Müttern; Appelle an Arbeitgeber und Steueranreize für Betriebskitas bleiben aber unverbindlich, ihre Wirkung auf Teilzeit ist offen.', 'gemischt', 'https://www.zew.de/PU80770', 'bund', null, true, 'blind'),
  (9495, 28, 'Haushaltsnahe Dienstleistungen staatlich fördern (Bund)', 'Zuschüsse oder Steuerabzug entlasten Haushalte bei Routinearbeit, verändern aber nicht die Aufteilung zwischen Partnern; Evaluationen in Belgien und Schweden können Effekte für die Nutzenden nicht sicher belegen. Ein neues Budget braucht Finanzierung.', 'offen', 'https://www.tillvaxtanalys.se/en-GB/publikationer/pm/pm/branschspecifikaskattelattnadereninternationelljamforelse.4573.html', 'bund', null, true, 'blind'),
  (9496, 28, 'Geschlechterrollen in Kita, Schule, Berufsorientierung und Fachkräfteausbildung thematisieren (Land)', 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'gemischt', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'land', null, true, 'blind')
