insert into public.abdeckung (thema_id, partei_id, land, art, begruendung, stand, ki_entwurf, durchsucht_fuer) values
  (28, 11, null, 'massnahmen', null, '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 11, 'BE', 'keine', 'Inhaltsverzeichnis, Kapitel ''Gewalt gegen Frauen'' (S. 11), ''Chancen bieten'' (S. 102-103) und ''Starke Familien'' (S. 108-109) gelesen. Nichts zu Rollenbildern oder widersprüchlichen Erwartungen an Mütter; Vereinbarkeit und Kita-Ausbau gehören zu anderen Ursachen.', '2026-10-08', true, '{2803}'),
  (28, 11, 'MV', 'keine', 'Inhaltsverzeichnis, Kapitel Familienland (S. 96-98), Gesundheit von Frauen (Gesundheitskapitel) und alle Textstellen zu Frauen, Mütter, Vereinbarkeit, Rollen per Volltextsuche gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter (2803).', '2026-10-08', true, '{2803}'),
  (28, 11, 'ST', 'keine', 'Kapitel Soziale Gerechtigkeit und Familie (S. 30-33), Frühkindliche Bildung (S. 48-50) und Justiz (S. 57-58) gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter. Nur Wahlfreiheit, Vereinbarkeit, Chancengleichheit in Führungspositionen und Sorgearbeit (andere Ursachen).', '2026-10-08', true, '{2803}'),
  (28, 12, null, 'massnahmen', null, '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 12, 'BE', 'keine', 'Inhaltsverzeichnis, Kapitel Gute Arbeit (S. 8), Zusammenleben, Familie und Gleichstellung (S. 47-48) und Fundstelle S. 11 gelesen; keine Zusage zu Rollenbildern oder Erwartungen an Mütter, nur Parität, Gleichstellungsgesetz, Pay Gap, Wiedereinstieg.', '2026-10-08', true, '{2803}'),
  (28, 12, 'MV', 'keine', 'Kapitel Gleichstellung (S. 38) und Leitsatz S. 6 gelesen. Zu Rollenbildern/Erwartungen an Mütter (2803) nur Rückblick (Führungspositionen in Landesverwaltung ergriffen) und allgemeine Ziele; Gewalt und Frauenhäuser gehören zu Sicherheit.', '2026-10-08', true, '{2803}'),
  (28, 12, 'ST', 'keine', 'Kapitel Gleichstellung auf dem Arbeitsmarkt (S. 9), Vielfalt/Diskriminierung (S. 36), Fundstelle S. 27 gelesen: nichts zu Rollenbildern oder Erwartungen an Mütter; Sorgearbeit-Zusagen (S. 9) gehören zu 2801, nicht Landesursache.', '2026-10-08', true, '{2803}'),
  (28, 13, null, 'massnahmen', null, '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 13, 'BE', 'keine', 'Kapitel 4.1 Strukturelle Gleichstellung (S. 130-133), Gleichstellung am Arbeitsplatz (S. 109-110) und Fundstelle S. 183 gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter. S. 183 meint Familienbildung/Sprach-Kitas.', '2026-10-08', true, '{2803}'),
  (28, 13, 'MV', 'keine', 'Kapitel 13 (S. 80-85) und Fundstelle S. 81 gelesen. Rollenbilder werden nur als Lagebeschreibung genannt; keine Zusage, die Rollenbilder oder Erwartungen an Mütter angeht. Care-Arbeit/Gleichstellung (S. 83-85) zählt nicht zu 2803.', '2026-10-08', true, '{2803}'),
  (28, 13, 'ST', 'massnahmen', null, '2026-10-08', true, '{2803}'),
  (28, 14, null, 'massnahmen', null, '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 14, 'BE', 'massnahmen', null, '2026-10-08', true, '{2803}'),
  (28, 14, 'MV', 'keine', 'Kapitel Familie (S. 37) und Fundstelle gelesen; Rollenbilder werden nur als Ziel genannt (sollen aufgebrochen werden), ohne Handlungszusage. Sonst nichts zu Müttern, Rollenerwartungen, Teilzeit oder Belästigung im Landesprogramm gefunden.', '2026-10-08', true, '{2803}'),
  (28, 14, 'ST', 'keine', 'Kapitel Gleichstellung und Frauenpolitik (S. 38-39) und Familien (S. 24) gelesen; nur Bekenntnis zu gleichberechtigter Erziehungs- und Erwerbsarbeit und allgemeine Weiterentwicklung des Frauenfördergesetzes, nichts zu Rollenbildern oder Erwartungen an Mütter.', '2026-10-08', true, '{2803}'),
  (28, 15, null, 'massnahmen', null, '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 15, 'BE', 'keine', 'Erfasste Stellen (S. 59) setzen laut Bewertung ohne Parteinamen an keiner der Ursachen an.', '2026-10-08', true, '{2803}'),
  (28, 15, 'MV', 'keine', 'Kapitel Familienland MV (S. 17-21) und Fundstellen S. 17, 19, 26 gelesen. Nur Leitbilder (Wahlfreiheit, positives Familienbild) und Kritik an Rollenbildern in der Schule; keine konkrete Zusage zu Rollenbildern oder Erwartungen an Mütter.', '2026-10-08', true, '{2803}'),
  (28, 15, 'ST', 'keine', 'Kapitel I. Familie und Kinder (S. 10-19), Gleichberechtigung (S. 94), Girls and Boys Day (S. 63) und Fundstelle S. 17 gelesen; nichts setzt an widersprüchlichen Erwartungen an Mütter an. S. 17 ist Kritik, keine Zusage.', '2026-10-08', true, '{2803}'),
  (28, 16, null, 'massnahmen', null, '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 16, 'BE', 'massnahmen', null, '2026-10-08', true, '{2803}'),
  (28, 16, 'MV', 'massnahmen', null, '2026-10-08', true, '{2803}'),
  (28, 16, 'ST', 'massnahmen', null, '2026-10-08', true, '{2803}'),
  (28, 17, null, 'keine', 'Kapitel Frauenrechte statt Gender-Ideologie (S. 33-34), Arbeit/Löhne (S. 18) und Fundstellen S. 5, 6, 15, 16, 22 gelesen. Nur Kita-, Ferienbetreuung und Frauenhäuser (R2: andere Themen) sowie Lagebeschreibung zu Sorgearbeit; nichts zu Aufteilung, Teilzeit-Wiedereinstieg, Rollenbildern oder Belästigung.', '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 17, 'BE', 'keine', 'Soziales/Familie (S. 10-13), Bildung, Sport (S. 27), Wirtschaft, Sicherheit/Frauenhäuser sowie Volltextsuche (Frauen, Mütter, Gleichstellung, Rollen, Vereinbarkeit) gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter. Frauenhäuser gehören zu Sicherheit (R2).', '2026-10-08', true, '{2803}'),
  (28, 17, 'MV', 'keine', 'Kapitel Familien (S. 11-12), Gute Arbeit (S. 19) und Frauenschutz (S. 69) gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter (2803). Vereinbarkeit/Gleichstellung am Arbeitsmarkt gehört nicht zu 2803.', '2026-10-08', true, '{2803}'),
  (28, 17, 'ST', 'keine', 'Kapitel ''Gleichstellung voranbringen'' (S. 37-39) und ''Gute Arbeit'' (S. 22) gelesen. Zu Rollenbildern und Erwartungen an Mütter nur Wahlfreiheit-Bekenntnis und Betreuungsfinanzierung (gehört zu Kita-Betreuung); keine Zusage gegen widersprüchliche Rollenerwartungen.', '2026-10-08', true, '{2803}'),
  (28, 18, null, 'massnahmen', null, '2026-10-08', true, '{2801,2802,2803,2804}'),
  (28, 18, 'BE', 'massnahmen', null, '2026-10-08', true, '{2803}'),
  (28, 18, 'MV', 'keine', 'Inhaltsverzeichnis, Kapitel Bildung, Gesellschaftlicher Zusammenhalt (S. 13-19, u.a. Diskriminierung) und Stichwortsuche (Frauen, Mütter, Gleichstellung, Geschlecht, Sexismus, Vereinbarkeit, Rollen) gelesen; keine Zusage zu Rollenbildern oder Erwartungen an Mütter.', '2026-10-08', true, '{2803}'),
  (28, 18, 'ST', 'keine', 'Inhaltsverzeichnis und Fundstelle S. 128 gelesen (Männerpolitik: moderne Rollenbilder für Männer, nicht Erwartungen an Mütter). Volltextsuche nach Frauen, Mütter, Rollenbild, Stereotyp, Elternzeit, Teilzeit, Vereinbarkeit ergab nur Gewalt-, Gesundheits- und Männerthemen.', '2026-10-08', true, '{2803}');
