  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9497, 28, 11, null, 'Elterngeld verbessern und den Partnerschaftsbonus für gleichzeitige vollzeitnahe Teilzeit beider Eltern weiterentwickeln.', '{2801}', 9493, 1, 3, null, 'ElterngeldPlus und Partnerschaftsbonus werden zunehmend genutzt, der Bonus aber nur von einem kleinen Teil der Väter; eine messbare Wirkung auf Aufteilung oder Rückkehr aus der Teilzeit ist kaum untersucht. Leicht im bestehenden Gesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=62', 'https://www.bundestag.de/webarchiv/textarchiv/2018/kw08-de-elterngeld-plus-542316', 'offen', '2026-10-08', false, true, 'blind'),
  (9498, 28, 11, null, 'Steuerliche Absetzbarkeit haushaltsnaher Dienstleistungen verbessern.', '{2801}', 9495, 1, 2, null, 'Zuschüsse oder Steuerabzug entlasten Haushalte bei Routinearbeit, verändern aber nicht die Aufteilung zwischen Partnern; Evaluationen in Belgien und Schweden können Effekte für die Nutzenden nicht sicher belegen. Ein neues Budget braucht Finanzierung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=15', 'https://www.tillvaxtanalys.se/en-GB/publikationer/pm/pm/branschspecifikaskattelattnadereninternationelljamforelse.4573.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9499, 28, 12, null, 'Elterngeld ausbauen: je sechs nicht übertragbare Monate pro Elternteil plus sechs frei verteilbare Monate.', '{2801}', 9491, 3, 2, null, 'Reservierte Monate für jeden Elternteil verschieben laut Québec- und Deutschland-Studien die Hausarbeit dauerhaft zu den Vätern. Die Verlängerung des Bezugs verursacht aber erhebliche Mehrkosten und braucht Finanzierung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://ideas.repec.org/a/ucp/jlabec/doi10.1086-703115.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9500, 28, 12, null, 'Familienstartzeit: bezahlte Freistellung für Väter oder Partnerinnen und Partner in den ersten zwei Wochen nach der Geburt.', '{2801}', 9492, 2, 3, null, 'Kurze Partnerfreistellung wird stark genutzt und erleichtert Müttern den Wiedereinstieg; in Spanien änderte sie die längerfristige Aufteilung aber kaum. Gesetzlich einfach, umlage- oder steuerfinanziert machbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.iza.org/publications/dp/10865', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9501, 28, 12, null, 'Jährliches Familienbudget für Alltagshelfer, das haushaltsnahe Dienstleistungen direkt fördert.', '{2801}', 9495, 1, 2, null, 'Zuschüsse oder Steuerabzug entlasten Haushalte bei Routinearbeit, verändern aber nicht die Aufteilung zwischen Partnern; Evaluationen in Belgien und Schweden können Effekte für die Nutzenden nicht sicher belegen. Ein neues Budget braucht Finanzierung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.tillvaxtanalys.se/en-GB/publikationer/pm/pm/branschspecifikaskattelattnadereninternationelljamforelse.4573.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9502, 28, 12, null, 'Allgemeines Gleichbehandlungsgesetz modernisieren und Antidiskriminierungsberatung ausbauen, für wirksameren Schutz vor Diskriminierung.', '{2804}', null, 1, 3, null, 'Mehr Beratung und ein reformiertes AGG können Betroffenen den Beschwerdeweg erleichtern; die Zusage bleibt allgemein und nennt sexuelle Belästigung am Arbeitsplatz nicht ausdrücklich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9503, 28, 13, null, 'Elternzeit so gestalten, dass jeder Elternteil mindestens ein Drittel nutzen kann, als Anreiz zu partnerschaftlicher Aufteilung.', '{2801}', 9490, 3, 3, null, 'Reservierte Partnermonate erhöhen die Elternzeit von Vätern deutlich; Studien aus Deutschland und Québec zeigen danach dauerhaft mehr Haus- und Sorgearbeit der Väter, in Schweden fand sich kein solcher Effekt. Umbau im bestehenden Elterngeld ohne große Mehrkosten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=82', 'https://www.rwi-essen.de/publikationen/zitationsansicht/gemischt/detail/fathers-parental-leave-taking-childcare-involvement-and-1043', 'belegt', '2026-10-08', false, true, 'blind'),
  (9504, 28, 13, null, 'Brückenteilzeit und Rückkehrrecht in Vollzeit ausweiten und individueller gestalten.', '{2802}', null, 2, 3, null, 'Ein breiteres Rückkehrrecht in Vollzeit setzt direkt an ungewollter Teilzeit an, da die heutige Brückenteilzeit viele kleine Betriebe ausnimmt und selten genutzt wird; eine Wirkungsevaluation fehlt. Änderung im Teilzeitgesetz.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9505, 28, 13, null, 'Minijobs schrittweise in sozialversicherungspflichtige Beschäftigung überführen, weil sie für Frauen zur Teilzeitfalle werden.', '{2802}', null, 2, 2, null, 'Minijobs verstärken mit Splitting und Mitversicherung geringe Stunden verheirateter Frauen; ihre Überführung würde diesen Anreiz abbauen. Wie viele Stunden tatsächlich steigen, ist unsicher; der schrittweise Umbau braucht Zeit.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2026/maerz/nach-kinderphase-ehegattensplitting-bremst-beschaeftigung-von-frauen-aus', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9506, 28, 13, 'ST', 'Schulungen in Kitas für geschlechterneutrale Erziehung, um stereotype Rollenbilder früh abzubauen', '{2803}', 9496, 1, 3, null, 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=58', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9507, 28, 14, null, 'Volles Elterngeld soll ausgezahlt werden, wenn beide Partner mindestens vier Monate nehmen; die übrigen Monate frei aufteilbar.', '{2801}', 9490, 3, 3, null, 'Reservierte Partnermonate erhöhen die Elternzeit von Vätern deutlich; Studien aus Deutschland und Québec zeigen danach dauerhaft mehr Haus- und Sorgearbeit der Väter, in Schweden fand sich kein solcher Effekt. Umbau im bestehenden Elterngeld ohne große Mehrkosten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', 'https://www.rwi-essen.de/publikationen/zitationsansicht/gemischt/detail/fathers-parental-leave-taking-childcare-involvement-and-1043', 'belegt', '2026-10-08', false, true, 'blind'),
  (9508, 28, 14, null, 'Arbeitszeitgesetz abschaffen, um flexible Arbeitszeiten, Teilzeit, Jobsharing und Homeoffice für Frauen wie Männer zu ermöglichen.', '{2802}', null, 1, 1, null, 'Flexiblere Arbeitszeiten können Vereinbarkeit erleichtern, ein Bezug zur Teilzeitfalle ist aber kaum belegt. Eine ersatzlose Abschaffung widerspräche der EU-Arbeitszeitrichtlinie (Höchstarbeitszeit, Ruhezeiten); nötig wäre eine Ersatzregelung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9509, 28, 14, 'BE', 'Eltern früh über tradierte Rollenbilder informieren; Kitas sollen geschlechtersensible Erziehung leben.', '{2803}', 9496, 1, 3, null, 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=81', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9510, 28, 15, null, 'Erziehungsgeld für die Eigenbetreuung in den ersten drei Lebensjahren sowie Hilfen beim beruflichen Wiedereinstieg.', '{2802}', null, 1, 1, null, 'Hilfen zum Wiedereinstieg setzen an langer Teilzeit an; ein Erziehungsgeld für Eigenbetreuung senkte in Westdeutschland aber leicht die Erwerbstätigkeit von Müttern. Ein Bundes-Betreuungsgeld wurde 2015 mangels Bundeskompetenz verworfen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', 'https://jhr.uwpress.org/node/11990', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9511, 28, 15, null, 'Arbeitgeber sollen Telearbeit, flexible Arbeitszeiten und Betriebskindergärten anbieten, damit Eltern Betreuung und Arbeit vereinbaren können.', '{2802}', 9494, 1, 3, null, 'Homeoffice erhöht laut Paneldaten die vertraglichen Stunden von Müttern; Appelle an Arbeitgeber und Steueranreize für Betriebskitas bleiben aber unverbindlich, ihre Wirkung auf Teilzeit ist offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=148', 'https://www.zew.de/PU80770', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9512, 28, 16, null, 'Einführung eines bezahlten Elternschutzes von 28 Tagen für den zweiten Elternteil ab Geburt, um Sorge- und Erwerbsarbeit partnerschaftlich aufzuteilen.', '{2801}', 9492, 2, 3, null, 'Kurze Partnerfreistellung wird stark genutzt und erleichtert Müttern den Wiedereinstieg; in Spanien änderte sie die längerfristige Aufteilung aber kaum. Gesetzlich einfach, umlage- oder steuerfinanziert machbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://www.iza.org/publications/dp/10865', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9513, 28, 16, null, 'Ausdrückliches Rückkehrrecht auf den gleichen oder einen gleichwertigen Arbeitsplatz nach der Elternzeit.', '{2802}', null, 1, 3, null, 'Ein Rückkehrrecht auf denselben oder gleichwertigen Arbeitsplatz erleichtert den Wiedereinstieg, schreibt aber weitgehend fest, was EU-Recht (Richtlinie 2019/1158) bereits vorsieht; zur Wirkung gibt es kaum Studien.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9514, 28, 16, null, 'Rechtsanspruch auf eine Vollzeitstelle und auf familienfreundliche Schichten.', '{2802}', null, 2, 2, null, 'Ein Anspruch auf Vollzeit und familienfreundliche Schichten setzt direkt an ungewollter Teilzeit an; Belege zur Wirkung fehlen. Ein allgemeiner Anspruch greift stark in betriebliche Planung ein und braucht Ausnahmen, daher aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9515, 28, 16, null, 'Arbeitsschutzgesetz um Gewalt und sexuelle Belästigung ergänzen, damit das Gesetz gegen Gewalt und Belästigung in der Arbeitswelt in der Praxis ankommt.', '{2804}', null, 2, 3, null, 'Belästigung als Pflicht im Arbeitsschutz (Gefährdungsbeurteilung, Aufsicht) macht Prävention und Beschwerdewege verbindlicher, wo 40 % die Beschwerdestelle nicht kennen; die Wirkung dieses Wegs ist kaum evaluiert. Einfache Gesetzesänderung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/pressemitteilungen/EN/2019/20191025_Study_sexual_harrasment.html', 'offen', '2026-10-08', false, true, 'blind'),
  (9516, 28, 16, 'BE', 'Aufklärung und Weiterbildung, besonders in Schulen, über Sexismus, häusliche Gewalt und stereotype Rollenbilder.', '{2803}', 9496, 1, 3, null, 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9517, 28, 16, 'MV', 'Berufsorientierung ohne Geschlechterstereotype; Girls'' Day und Boys'' Day in Klasse 9 verpflichtend.', '{2803}', 9496, 1, 3, null, 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=15', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9518, 28, 16, 'MV', 'Genderkompetenz verbindlich in der Ausbildung von Lehrkräften und pädagogischen Fachkräften verankern, um Rollenmuster aufzubrechen.', '{2803}', 9496, 1, 3, null, 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9519, 28, 16, 'ST', 'Kinder und Jugendliche früh für alltägliche Aufgaben sensibilisieren, damit Sorgearbeit besser verteilt wird.', '{2803}', 9496, 1, 3, null, 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=22', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9520, 28, 18, null, 'Achtwöchiger Vaterschaftsurlaub und dreimonatige Mindest-Elternzeit je Elternteil, um Familienarbeit partnerschaftlich aufzuteilen', '{2801}', 9491, 3, 2, null, 'Reservierte Monate für jeden Elternteil verschieben laut Québec- und Deutschland-Studien die Hausarbeit dauerhaft zu den Vätern. Die Verlängerung des Bezugs verursacht aber erhebliche Mehrkosten und braucht Finanzierung.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=149', 'https://ideas.repec.org/a/ucp/jlabec/doi10.1086-703115.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9521, 28, 18, null, 'Ehegattensplitting abschaffen und jedem Elternteil einen eigenen Elterngeld-Anspruch auf sieben Monate geben', '{2801}', null, 3, 2, null, 'Eigene Elterngeldmonate je Elternteil verschieben belegt Sorgearbeit zu Vätern; das Splitting bremst laut Studien die Stundenausweitung von Ehefrauen. Eine Abschaffung muss aber das Existenzminimum des Partners sichern und betrifft Bestandsehen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=52', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2026/maerz/nach-kinderphase-ehegattensplitting-bremst-beschaeftigung-von-frauen-aus', 'belegt', '2026-10-08', false, true, 'blind'),
  (9522, 28, 18, null, 'Teilzeit-Elterngeld attraktiver gestalten und fördern', '{2802}', 9493, 1, 3, null, 'ElterngeldPlus und Partnerschaftsbonus werden zunehmend genutzt, der Bonus aber nur von einem kleinen Teil der Väter; eine messbare Wirkung auf Aufteilung oder Rückkehr aus der Teilzeit ist kaum untersucht. Leicht im bestehenden Gesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=149', 'https://www.bundestag.de/webarchiv/textarchiv/2018/kw08-de-elterngeld-plus-542316', 'offen', '2026-10-08', false, true, 'blind'),
  (9523, 28, 18, null, 'Flexible Arbeitszeitmodelle ausbauen und betriebliche Kinderbetreuung steuerlich fördern, um Beruf und Familie besser zu vereinbaren', '{2802}', 9494, 1, 3, null, 'Homeoffice erhöht laut Paneldaten die vertraglichen Stunden von Müttern; Appelle an Arbeitgeber und Steueranreize für Betriebskitas bleiben aber unverbindlich, ihre Wirkung auf Teilzeit ist offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=151', 'https://www.zew.de/PU80770', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9524, 28, 18, 'BE', 'Pflichtfach Lebenskompetenz an Schulen (Pilotschulen), das auch die kritische Auseinandersetzung mit Rollenbildern behandelt', '{2803}', 9496, 1, 3, null, 'Ein Schulexperiment in Indien veränderte Rollenbilder messbar und dauerhaft; Evaluationen hier messen meist Zufriedenheit, die Wirkung auf Erwartungen an Mütter ist offen. Liegt in Landeszuständigkeit und ist günstig umsetzbar.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=48', 'https://www.aeaweb.org/doi/10.1257/aer.20201112', 'gemischt', '2026-10-08', false, true, 'blind');

